def pathCounts(root):
	has = {}

	def fun(root, row):
		if root is None:
			return
		if root.left == None and root.right == None:
			if row in has:
				has[row] += 1
			else:
				has[row] = 1
			return
		fun(root.left, row + 1)
		fun(root.right, row + 1)
	fun(root, 1)
	for (key, value) in has.items():
		print('{} {}'.format(key, value), '$', end='')
